-- Venue Live Guest "Wedding Minimalist Sculptural". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara sculpt), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'sculpt', 'Wedding Minimalist Sculptural', 'sculpt', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 163, 'center 38%',
  $t${"name":"Wedding Minimalist Sculptural","orn":"diamond","ui":{"ivory":"#FBF8F2","white":"#FFFFFF","soft":"#EFE6D8","soft2":"#D8C6A6","accent":"#B08D4F","deep":"#4F4234","ink":"#43382C","mute":"#9A8F7E","line":"#E8DDCB","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFDF8","ink":"#43382C","accent":"#B08D4F","gold":"#D9A93F","leaf":"#EFE6D8","hbg":"rgba(251,248,242,.94)","hline":"#D9A93F","motif":"diamond"},"hud":{"bg":"rgba(79,66,52,.9)","acc":"#F2D27A","on":"#4F4234"},"scr":{"wine":"#B08D4F","veil":"251,248,242"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'sculpt');
